cat > /bot/src/wallrun.py <<'EOF'
import sys,time,math,json
sys.path.insert(0,'/bot/src')
from robot import Robot
from drive import Drive, angdiff

r=Robot(); d=Drive(r)
log=open('/memory/run.log','a')
def L(*a):
    log.write('%.1f %s\n'%(time.time(),' '.join(str(x) for x in a))); log.flush()
L('=== wallrun start (right-hand) ===')

AXES=[5,95,185,275]
while r.h is None or r.rays is None:
    r.update(); time.sleep(0.05)

def clearance():
    best={ax:0.0 for ax in AXES}
    for s in range(3):
        r.update()
        for ax in AXES:
            rel=((ax-r.h)%360)/22.5
            k0=int(rel)%16; k1=(k0+1)%16
            vals=[v for v in (r.ray(k0),r.ray(k1)) if v is not None]
            if vals: best[ax]=max(best[ax],min(vals))
        time.sleep(0.07)
    return best

last_tx=0; goal_seen=False; step=0
cur=5  # current axis heading
cx,cy=0.0,0.0  # rough position by steps
DIRV={5:(1,0),95:(0,1),185:(-1,0),275:(0,-1)}
while True:
    r.update()
    now=time.time()
    for m in r.msgs: L('RX:',m)
    r.msgs=[]
    for e in r.events:
        if 'goal=0' not in e: L('EV:',e)
        if 'goal=1' in e: goal_seen=True
    r.events=[]
    if now-last_tx>2:
        r.tx.write('A pos %.2f %.2f goal %d'%(cx,cy,1 if goal_seen else 0))
        last_tx=now
    if goal_seen:
        L('AT GOAL, holding position. steps=%d pos=%.1f,%.1f'%(step,cx,cy))
        r.wheels(0,0)
        while True:
            r.update()
            for m in r.msgs: L('RX:',m)
            r.msgs=[]
            if time.time()-last_tx>1:
                r.tx.write('A at_goal 1'); last_tx=time.time()
            time.sleep(0.2)
    c=clearance()
    # right-hand rule: right of heading cur is cur-90
    order=[(cur-90)%360,cur,(cur+90)%360,(cur+180)%360]
    order=[a if a!=0 else 360 for a in order]
    # normalize to AXES values (5,95,185,275)
    def nrm(a):
        return min(AXES,key=lambda x:abs(angdiff(x,a)))
    order=[nrm(a) for a in order]
    moved=False
    for ax in order:
        if c[ax]<0.42: continue
        if abs(angdiff(ax,r.h))>8: d.turn_to(ax)
        tr,reason=d.forward(0.5,target_h=ax,front_stop=0.23,speed=75)
        step+=1
        if tr>0.28:
            cur=ax; v=DIRV[ax]; cx+=v[0]; cy+=v[1]
            L('w%d %s tr=%.2f pos %.0f,%.0f c=%s'%(step,ax,tr,cx,cy,{a:round(x,2) for a,x in c.items()}))
            moved=True
            break
        else:
            L('w%d %s BLOCKED tr=%.2f'%(step,ax,tr))
            # nudge back to center
            d.forward(-0)  # noop
            break
    if not moved and all(c[a]<0.42 for a in AXES):
        L('boxed in?? c=%s'%c); time.sleep(0.5)
